final_template:
AWSTemplateFormatVersion: "2010-09-09"
Description: "Serverless Slot Machine Web Application with automated deployment and anonymous access"

Resources:
  AssetsBucket:
    Type: AWS::S3::Bucket
    Properties:
      WebsiteConfiguration:
        IndexDocument: index.html
        ErrorDocument: error.html
      PublicAccessBlockConfiguration:
        BlockPublicAcls: false
        IgnorePublicAcls: false
        BlockPublicPolicy: false
        RestrictPublicBuckets: false

  AssetsBucketPolicy:
    Type: AWS::S3::BucketPolicy
    Properties:
      Bucket: !Ref AssetsBucket
      PolicyDocument:
        Version: "2012-10-17"
        Statement:
          - Sid: PublicReadGetObject
            Effect: Allow
            Principal: "*"
            Action: s3:GetObject
            Resource: !Sub "${AssetsBucket.Arn}/*"

  SlotLambdaExecutionRole:
    Type: AWS::IAM::Role
    Properties:
      AssumeRolePolicyDocument:
        Version: "2012-10-17"
        Statement:
          - Effect: Allow
            Principal:
              Service: lambda.amazonaws.com
            Action: sts:AssumeRole
      Path: "/"
      Policies:
        - PolicyName: SlotLambdaLogsPolicy
          PolicyDocument:
            Version: "2012-10-17"
            Statement:
              - Effect: Allow
                Action:
                  - logs:CreateLogGroup
                  - logs:CreateLogStream
                  - logs:PutLogEvents
                Resource: "arn:aws:logs:*:*:*"

  SlotSimulationLambda:
    Type: AWS::Lambda::Function
    Properties:
      Handler: index.handler
      Runtime: nodejs22.x
      Role: !GetAtt SlotLambdaExecutionRole.Arn
      Code:
        ZipFile: |
          // Slot Machine Simulation Lambda Function
          exports.handler = async (event) => {
              // Define a set of card symbols for the slot machine
              const symbols = ['Cherry', 'Lemon', 'Seven', 'Bell', 'Bar'];
              // Generate three random symbols
              const result = [
                  symbols[Math.floor(Math.random() * symbols.length)],
                  symbols[Math.floor(Math.random() * symbols.length)],
                  symbols[Math.floor(Math.random() * symbols.length)]
              ];
              // Determine win if all three symbols match
              const win = (result[0] === result[1] && result[1] === result[2]);
              // Return the spin result and win status
              return {
                  spinResult: result,
                  win: win
              };
          };

  WebsiteSetupLambdaExecutionRole:
    Type: AWS::IAM::Role
    Properties:
      AssumeRolePolicyDocument:
        Version: "2012-10-17"
        Statement:
          - Effect: Allow
            Principal:
              Service: lambda.amazonaws.com
            Action: sts:AssumeRole
      Path: "/"
      Policies:
        - PolicyName: WebsiteSetupLambdaPolicy
          PolicyDocument:
            Version: "2012-10-17"
            Statement:
              - Effect: Allow
                Action:
                  - logs:CreateLogGroup
                  - logs:CreateLogStream
                  - logs:PutLogEvents
                Resource: "arn:aws:logs:*:*:*"
              - Effect: Allow
                Action:
                  - s3:PutObject
                  - s3:PutObjectAcl
                  - s3:GetObject
                  - s3:ListBucket
                Resource:
                  - !Sub "${AssetsBucket.Arn}"
                  - !Sub "${AssetsBucket.Arn}/*"

  WebsiteSetupLambda:
    Type: AWS::Lambda::Function
    Properties:
      Handler: index.handler
      Runtime: nodejs22.x
      Role: !GetAtt WebsiteSetupLambdaExecutionRole.Arn
      Timeout: 300
      Code:
        ZipFile: |
          // Custom Resource Lambda Function for setting up website assets
          const AWS = require('aws-sdk');
          const s3 = new AWS.S3();
          exports.handler = async (event, context) => {
              console.log("WebsiteSetupLambda received event:", JSON.stringify(event));
              const bucketName = event.ResourceProperties.BucketName;
              const cognitoPoolId = event.ResourceProperties.CognitoIdentityPoolId;
              const region = event.ResourceProperties.Region;
              const htmlContent = `
              <html>
                <head>
                  <title>Slot Machine</title>
                </head>
                <body>
                  <h1>Welcome to the Slot Machine</h1>
                  <p>Your Cognito Identity Pool ID: ${cognitoPoolId}</p>
                  <p>AWS Region: ${region}</p>
                  <script>
                    // Frontend JavaScript can now use these configurations to request AWS credentials
                  </script>
                </body>
              </html>`;
              try {
                  await s3.putObject({
                      Bucket: bucketName,
                      Key: 'index.html',
                      Body: htmlContent,
                      ContentType: 'text/html',
                      ACL: 'public-read'
                  }).promise();
                  await s3.putObject({
                      Bucket: bucketName,
                      Key: 'error.html',
                      Body: '<html><body><h1>Error occurred</h1></body></html>',
                      ContentType: 'text/html',
                      ACL: 'public-read'
                  }).promise();
                  await sendResponse(event, context, "SUCCESS", {Message: "Website assets setup complete"}, bucketName);
                  return;
              } catch (err) {
                  console.error("Error in WebsiteSetupLambda:", err);
                  await sendResponse(event, context, "FAILED", {Message: "Website assets setup failed"});
                  return;
              }

              async function sendResponse(event, context, responseStatus, responseData, physicalResourceId) {
                  const https = require('https');
                  const url = require('url');
                  const responseBody = JSON.stringify({
                      Status: responseStatus,
                      Reason: "See details in CloudWatch Log: " + context.logStreamName,
                      PhysicalResourceId: physicalResourceId || context.logStreamName,
                      StackId: event.StackId,
                      RequestId: event.RequestId,
                      LogicalResourceId: event.LogicalResourceId,
                      Data: responseData
                  });
                  console.log("WebsiteSetupLambda response body:", responseBody);
                  const parsedUrl = url.parse(event.ResponseURL);
                  const options = {
                      hostname: parsedUrl.hostname,
                      port: 443,
                      path: parsedUrl.path,
                      method: 'PUT',
                      headers: {
                          'Content-Length': Buffer.byteLength(responseBody)
                      }
                  };
                  await new Promise((resolve, reject) => {
                      const req = https.request(options, (res) => {
                          console.log("WebsiteSetupLambda sendResponse status code:", res.statusCode);
                          resolve();
                      });
                      req.on('error', (error) => {
                          console.error("WebsiteSetupLambda sendResponse error:", error);
                          reject(error);
                      });
                      req.write(responseBody);
                      req.end();
                  });
              }
          };

  CognitoRoleAttachmentLambdaExecutionRole:
    Type: AWS::IAM::Role
    Properties:
      AssumeRolePolicyDocument:
        Version: "2012-10-17"
        Statement:
          - Effect: Allow
            Principal:
              Service: lambda.amazonaws.com
            Action: sts:AssumeRole
      Path: "/"
      Policies:
        - PolicyName: CognitoRoleAttachmentPolicy
          PolicyDocument:
            Version: "2012-10-17"
            Statement:
              - Effect: Allow
                Action:
                  - logs:CreateLogGroup
                  - logs:CreateLogStream
                  - logs:PutLogEvents
                Resource: "arn:aws:logs:*:*:*"
              - Effect: Allow
                Action:
                  - cognito-identity:SetIdentityPoolRoles
                Resource: "*"

  CognitoRoleAttachmentLambda:
    Type: AWS::Lambda::Function
    Properties:
      Handler: index.handler
      Runtime: nodejs22.x
      Role: !GetAtt CognitoRoleAttachmentLambdaExecutionRole.Arn
      Timeout: 180
      Code:
        ZipFile: |
          const https = require('https');
          const url = require('url');
          const AWS = require('aws-sdk');
          const cognitoIdentity = new AWS.CognitoIdentity();

          async function sendResponse(event, context, responseStatus, responseData, physicalResourceId) {
              const responseBody = JSON.stringify({
                  Status: responseStatus,
                  Reason: "See CloudWatch Log: " + context.logStreamName,
                  PhysicalResourceId: physicalResourceId || context.logStreamName,
                  StackId: event.StackId,
                  RequestId: event.RequestId,
                  LogicalResourceId: event.LogicalResourceId,
                  Data: responseData
              });
              console.log("CognitoRoleAttachmentLambda response body:", responseBody);
              const parsedUrl = url.parse(event.ResponseURL);
              const options = {
                  hostname: parsedUrl.hostname,
                  port: 443,
                  path: parsedUrl.path,
                  method: 'PUT',
                  headers: {
                      'Content-Length': Buffer.byteLength(responseBody)
                  }
              };
              console.log("CognitoRoleAttachmentLambda sending response...");
              await new Promise((resolve, reject) => {
                  const req = https.request(options, (res) => {
                      console.log("CognitoRoleAttachmentLambda sendResponse status code:", res.statusCode);
                      resolve();
                  });
                  req.on('error', (error) => {
                      console.error("CognitoRoleAttachmentLambda sendResponse error:", error);
                      reject(error);
                  });
                  req.write(responseBody);
                  req.end();
              });
          }

          exports.handler = async (event, context) => {
              console.log("CognitoRoleAttachmentLambda received event:", JSON.stringify(event));

              if (event.RequestType === "Delete" || event.RequestType === "Update") {
                  try {
                      await sendResponse(event, context, "SUCCESS", {Message: `${event.RequestType} request received`}, event.ResourceProperties.IdentityPoolId);
                      return;
                  } catch (err) {
                      console.error("CognitoRoleAttachmentLambda error in Delete/Update:", err);
                      return;
                  }
              }

              const identityPoolId = event.ResourceProperties.IdentityPoolId;
              const authRoleArn = event.ResourceProperties.AuthRoleArn;
              const unauthRoleArn = event.ResourceProperties.UnauthRoleArn;
              const params = {
                  IdentityPoolId: identityPoolId,
                  Roles: {
                      authenticated: authRoleArn,
                      unauthenticated: unauthRoleArn
                  }
              };
              try {
                  await cognitoIdentity.setIdentityPoolRoles(params).promise();
                  await sendResponse(event, context, "SUCCESS", {Message: "Cognito roles attached"}, identityPoolId);
                  return;
              } catch (error) {
                  console.error("CognitoRoleAttachmentLambda error setting roles:", error);
                  await sendResponse(event, context, "FAILED", {Message: "Cognito roles attachment failed"});
                  return;
              }
          };

  CognitoRoleAttachmentCustomResource:
    Type: Custom::CognitoRoleAttachment
    DependsOn:
      - CognitoIdentityPool
      - CognitoAuthRole
      - CognitoUnauthRole
    Properties:
      ServiceToken: !GetAtt CognitoRoleAttachmentLambda.Arn
      IdentityPoolId: !Ref CognitoIdentityPool
      AuthRoleArn: !GetAtt CognitoAuthRole.Arn
      UnauthRoleArn: !GetAtt CognitoUnauthRole.Arn

  CognitoIdentityPool:
    Type: AWS::Cognito::IdentityPool
    Properties:
      IdentityPoolName: "SlotMachineIdentityPool"
      AllowUnauthenticatedIdentities: true

  CognitoUnauthRole:
    Type: AWS::IAM::Role
    Properties:
      AssumeRolePolicyDocument:
        Version: "2012-10-17"
        Statement:
          - Effect: Allow
            Principal:
              Federated: cognito-identity.amazonaws.com
            Action: sts:AssumeRoleWithWebIdentity
            Condition:
              StringEquals:
                cognito-identity.amazonaws.com:aud: !Ref CognitoIdentityPool
              "ForAnyValue:StringLike":
                cognito-identity.amazonaws.com:amr: unauthenticated
      Policies:
        - PolicyName: InvokeSlotLambdaPolicy
          PolicyDocument:
            Version: "2012-10-17"
            Statement:
              - Effect: Allow
                Action: lambda:InvokeFunction
                Resource: !GetAtt SlotSimulationLambda.Arn

  CognitoAuthRole:
    Type: AWS::IAM::Role
    Properties:
      AssumeRolePolicyDocument:
        Version: "2012-10-17"
        Statement:
          - Effect: Allow
            Principal:
              Federated: cognito-identity.amazonaws.com
            Action: sts:AssumeRoleWithWebIdentity
            Condition:
              StringEquals:
                cognito-identity.amazonaws.com:aud: !Ref CognitoIdentityPool
              "ForAnyValue:StringLike":
                cognito-identity.amazonaws.com:amr: authenticated
      Policies:
        - PolicyName: InvokeSlotLambdaPolicy
          PolicyDocument:
            Version: "2012-10-17"
            Statement:
              - Effect: Allow
                Action: lambda:InvokeFunction
                Resource: !GetAtt SlotSimulationLambda.Arn

  WebsiteSetupCustomResource:
    Type: Custom::WebsiteSetup
    DependsOn:
      - CognitoRoleAttachmentCustomResource
    Properties:
      ServiceToken: !GetAtt WebsiteSetupLambda.Arn
      BucketName: !Ref AssetsBucket
      CognitoIdentityPoolId: !Ref CognitoIdentityPool
      Region: !Ref "AWS::Region"
      PrebuiltZipUrl: "https://example.com/prebuilt-site.zip"

Outputs:
  WebsiteURL:
    Description: "URL for the slot machine website"
    Value: !GetAtt AssetsBucket.WebsiteURL
  CognitoIdentityPoolId:
    Description: "Cognito Identity Pool ID"
    Value: !Ref CognitoIdentityPool
